
(function(){
  if (window.__cpChatLoaded) return; window.__cpChatLoaded = true;

  // Ensure root exists
  let root = document.getElementById("cp-chat-root");
  if (!root) { root = document.createElement("div"); root.id="cp-chat-root"; document.body.appendChild(root); }

  // Inject CSS once
  if(!document.getElementById('cp-chat-style')){
    const s=document.createElement('style'); s.id='cp-chat-style'; s.textContent=`  :root{
    --cp-accent:#ff6b4a;
    --cp-accent2:#ff8c70;
    --cp-text:#f3f3f3;
    --cp-muted:#121212;
    --cp-bg:#0a0a0a;
    --cp-border:#262626;
    --cp-radius:18px;
    --cp-shadow:0 22px 44px rgba(0,0,0,.55);
    --cp-font: Inter, system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif;
    --cp-size:1rem;
  }
  #cp-chat-root *{ box-sizing:border-box; }
  .cp-launcher{
    position:fixed; right:22px; bottom:22px;
    width:60px; height:60px; border-radius:50%;
    background:linear-gradient(135deg, var(--cp-accent) 0%, var(--cp-accent2) 100%);
    display:grid; place-items:center;
    border:1px solid rgba(255,255,255,.08);
    box-shadow:var(--cp-shadow);
    cursor:pointer; z-index:9999;
    transition: transform 0.2s ease, box-shadow .2s ease;
  }
  .cp-launcher:hover { transform: scale(1.06); box-shadow:0 26px 58px rgba(255,107,74,.35); }
  .cp-launcher svg{ width:30px; height:30px; color:#fff; opacity:.98; }
  .cp-panel{
    position:fixed; right:22px; bottom:92px;
    width:390px; max-width:calc(100vw - 44px);
    background:var(--cp-bg);
    border:1px solid var(--cp-border);
    border-radius:var(--cp-radius);
    box-shadow:var(--cp-shadow);
    overflow:hidden; display:none; z-index:9999;
    font-family:var(--cp-font); font-size:var(--cp-size); color:var(--cp-text);
    max-height:600px;
  }
  .cp-header{
    display:flex; align-items:center; gap:12px; padding:12px 16px;
    background:linear-gradient(90deg, #151515 0%, #0f0f0f 100%);
    border-bottom:1px solid var(--cp-border); position:relative;
  }
  .cp-avatar{
    width:28px; height:28px; border-radius:8px;
    background:linear-gradient(135deg, var(--cp-accent), var(--cp-accent2));
    display:grid; place-items:center; font-weight:700; color:#fff; font-size:16px;
  }
  .cp-title{ font-weight:600; font-size:0.95rem; flex:1; color:#fff; }
  .cp-close{
    width:28px; height:28px; border-radius:8px; background:transparent; border:1px solid var(--cp-border);
    display:grid; place-items:center; cursor:pointer; color:#a3a3a3; transition:all 0.2s;
  }
  .cp-close:hover{ background:#1b1b1b; color:#fff; border-color:#3a3a3a; }
  .cp-close svg{ width:18px; height:18px; }
  .cp-body{
    background:var(--cp-muted); height:280px; overflow-y:auto; padding:12px;
    display:flex; flex-direction:column;
  }
  .cp-body.with-lead{ height:180px; }
  .cp-msg{
    max-width:86%; line-height:1.55; padding:10px 14px; margin:6px 0;
    border-radius:14px; word-wrap:break-word; font-size:0.92rem;
  }
  .cp-msg.user{
    margin-left:auto;
    background:linear-gradient(135deg, var(--cp-accent), var(--cp-accent2));
    color:#fff; border-top-right-radius:5px; text-align:right;
    box-shadow:0 6px 16px rgba(255,107,74,.25);
  }
  .cp-msg.bot{
    background:#161616; border:1px solid #2a2a2a; color:#e8e8e8; border-top-left-radius:5px;
  }
  .cp-msg.typing{ font-style:italic; opacity:.7; }
  .cp-lead{
    background:#0e0e0e; border-top:1px solid var(--cp-border); padding:12px 16px; display:none;
  }
  .cp-lead-title{ font-weight:600; margin-bottom:10px; font-size:0.9rem; color:#fff; }
  .cp-lead-grid{ display:grid; gap:8px; margin-bottom:10px; }
  .cp-lead-note{ font-size:0.75rem; color:#9aa0a6; margin-top:8px; text-align:center; line-height:1.3; }
  .cp-lead-note.error{ color:#ff6b4a; }
  .cp-footer{
    display:flex; gap:8px; padding:10px; background:#0e0e0e; border-top:1px solid var(--cp-border);
  }
  .cp-input{
    flex:1; font:inherit; background:#0f0f0f; color:#fff;
    border:1px solid #2a2a2a; border-radius:10px; padding:10px 12px; outline:none; font-size:0.92rem;
    transition:border-color .2s, box-shadow .2s;
  }
  .cp-input::placeholder{ color:#7a7a7a; }
  .cp-input:focus{ border-color:var(--cp-accent); box-shadow:0 0 0 2px rgba(255,107,74,.15); }
  .cp-send{
    font:600 0.9rem/1 var(--cp-font); color:#fff;
    background:linear-gradient(135deg, var(--cp-accent), var(--cp-accent2));
    border:1px solid rgba(255,255,255,.08); border-radius:10px; padding:10px 14px; cursor:pointer;
    transition:transform .1s, box-shadow .2s, filter .2s;
  }
  .cp-send:hover{ filter:brightness(1.05); box-shadow:0 8px 22px rgba(255,107,74,.28); }
  .cp-send:active{ transform:scale(.96); }
  .cp-send:disabled{ opacity:.55; cursor:not-allowed; }
  @media(max-width:480px){
    .cp-panel{ width:100%; right:0; bottom:0; border-radius:16px 16px 0 0; max-height:85vh; }
    .cp-body{ height:calc(85vh - 250px); }
    .cp-body.with-lead{ height:calc(85vh - 380px); }
  }`; document.head.appendChild(s);
  }

  // Endpoints
  const CHAT_ENDPOINT = "https://wisewavesllc.zeabur.app/webhook/chat2";
  const LEAD_ENDPOINT = "https://wisewavesllc.zeabur.app/webhook/chat2/lead";

  // Build Panel
  const panel = document.createElement("div");
  panel.className = "cp-panel";
  panel.innerHTML = `
    <div class="cp-header">
      <div class="cp-avatar">AI</div>
      <div class="cp-title">OneSource Cloud AI Support</div>
      <button id="cp-close" class="cp-close" title="Close chat">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
          <line x1="18" y1="6" x2="6" y2="18"></line>
          <line x1="6" y1="6" x2="18" y2="18"></line>
        </svg>
      </button>
    </div>
    <div class="cp-body" id="cp-body"></div>

    <div class="cp-lead" id="cp-lead">
      <div class="cp-lead-title">🚀 Before we start, may I know your name and email?</div>
      <div class="cp-lead-grid">
        <input id="cp-name" class="cp-input" placeholder="Your name *" autocomplete="name" />
        <input id="cp-email" class="cp-input" placeholder="Your email *" type="email" autocomplete="email" />
      </div>
      <button id="cp-lead-save" class="cp-send" style="width:100%;">Continue Chat</button>
      <div id="cp-lead-note" class="cp-lead-note">We'll only use this to follow up on your question.</div>
    </div>

    <div class="cp-footer">
      <input id="cp-input" class="cp-input" placeholder="Ask about Private AI, GPUs, or infrastructure..." />
      <button id="cp-send" class="cp-send">Send</button>
    </div>
  `;

  const launcher = document.createElement("button");
  launcher.className = "cp-launcher";
  launcher.setAttribute("aria-label","Open chat");
  launcher.innerHTML = `<svg viewBox="0 0 24 24" fill="currentColor"><path d="M12 3c4.97 0 9 3.58 9 8s-4.03 8-9 8a10.9 10.9 0 0 1-3.6-.6L4 21l1.8-3.6A9.6 9.6 0 0 1 3 11c0-4.42 4.03-8 9-8z"/></svg>`;

  root.append(panel, launcher);

  const body = panel.querySelector("#cp-body");
  const input = panel.querySelector("#cp-input");
  const send = panel.querySelector("#cp-send");
  const leadUI = panel.querySelector("#cp-lead");
  const nameEl = panel.querySelector("#cp-name");
  const mailEl = panel.querySelector("#cp-email");
  const saveBt = panel.querySelector("#cp-lead-save");
  const noteEl = panel.querySelector("#cp-lead-note");
  const closeBtn = panel.querySelector("#cp-close");

  const SID_KEY="cp_chat_sid", LEAD_NAME="cp_lead_name", LEAD_MAIL="cp_lead_email";
  let sessionId = localStorage.getItem(SID_KEY) || Math.random().toString(36).slice(2);
  localStorage.setItem(SID_KEY, sessionId);

  let lead = { name:localStorage.getItem(LEAD_NAME)||"", email:localStorage.getItem(LEAD_MAIL)||"" };
  let leadCaptured = !!(lead.name && lead.email);
  let pendingMessage = "";

  function toggle(){
    const open = panel.style.display==="block";
    panel.style.display = open?"none":"block";
    if(!open){
      if(!leadCaptured){ showLeadForm(); } else { input.focus(); }
    }
  }
  launcher.addEventListener("click",toggle);
  closeBtn.addEventListener("click",toggle);
  document.addEventListener("keydown",e=>{ if(e.key==="Escape" && panel.style.display==="block") toggle(); });

  function showLeadForm(){ leadUI.style.display="block"; body.classList.add("with-lead"); nameEl.focus(); }
  function hideLeadForm(){ leadUI.style.display="none"; body.classList.remove("with-lead"); }

  function addMsg(text,who="bot"){
    const typing = body.querySelector(".cp-msg.typing");
    if(typing) typing.remove();
    const div=document.createElement("div");
    div.className=`cp-msg ${who}`;
    div.textContent=text;
    body.appendChild(div);
    body.scrollTop=body.scrollHeight;
  }
  function showTyping(){
    const div=document.createElement("div");
    div.className="cp-msg bot typing";
    div.textContent="AI is typing...";
    body.appendChild(div);
    body.scrollTop=body.scrollHeight;
  }

  async function readResponse(res){
    const ct = res.headers.get("content-type") || "";
    if(!res.ok){
      const err = ct.includes("application/json") ? await res.json().catch(()=>({})) : await res.text();
      throw new Error(`HTTP ${res.status}: ${typeof err==='string'?err:JSON.stringify(err)}`);
    }
    return ct.includes("application/json") ? res.json() : res.text();
  }

  async function sendLeadToWebhook(name,email){
    if(!LEAD_ENDPOINT) return;
    try{
      const form = new URLSearchParams();
      form.set("name", name);
      form.set("email", email);
      form.set("source", "onesource-chatbot");
      form.set("sessionId", sessionId);
      form.set("timestamp", new Date().toISOString());
      const res = await fetch(LEAD_ENDPOINT,{
        method:"POST",
        mode:"cors",
        headers:{ "Content-Type":"application/x-www-form-urlencoded;charset=UTF-8", "Accept":"application/json" },
        body:form
      });
      await readResponse(res);
    }catch(e){ console.warn("Lead webhook failed (non-fatal)", e); }
  }

  async function sendMsg(){
    const text=(input.value||"").trim();
    if(!text) return;
    if(!leadCaptured){
      pendingMessage=text; input.value=""; addMsg(text,"user"); showLeadForm();
      nameEl.value=lead.name||""; mailEl.value=lead.email||"";
      noteEl.textContent="Please provide your contact info to continue."; noteEl.className="cp-lead-note";
      return;
    }
    await sendToChat(text);
  }

  async function sendToChat(text){
    addMsg(text,"user"); input.value=""; send.disabled=true; showTyping();
    try{
      const form=new URLSearchParams();
      form.set("sessionId",sessionId);
      form.set("message",text);
      if(lead.name) form.set("name",lead.name);
      if(lead.email) form.set("email",lead.email);

      const res = await fetch(CHAT_ENDPOINT,{
        method:"POST",
        mode:"cors",
        headers:{ "Content-Type":"application/x-www-form-urlencoded;charset=UTF-8", "Accept":"application/json" },
        body:form
      });

      const data = await readResponse(res);
      const reply = (data && data.reply) ? data.reply : (typeof data==='string' ? data : "");
      addMsg(reply || "Sorry, I didn't catch that.");
    }catch(err){
      addMsg("Connection error. Please try again.");
      console.error("Chat error:",err);
    }finally{
      send.disabled=false; input.focus();
    }
  }

  saveBt.addEventListener("click",async()=>{
    const name=(nameEl.value||"").trim();
    const email=(mailEl.value||"").trim();
    if(!name||!email){ noteEl.textContent="⚠️ Please enter both name and email."; noteEl.className="cp-lead-note error"; return; }
    if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)){ noteEl.textContent="⚠️ Please enter a valid email."; noteEl.className="cp-lead-note error"; return; }

    saveBt.disabled=true; saveBt.textContent="Saving...";
    lead={name,email};
    localStorage.setItem(LEAD_NAME,name);
    localStorage.setItem(LEAD_MAIL,email);
    leadCaptured=true;
    await sendLeadToWebhook(name,email);
    hideLeadForm();
    saveBt.disabled=false; saveBt.textContent="Continue Chat";

    if(pendingMessage){ const msg=pendingMessage; pendingMessage=""; await sendToChat(msg); }
    else{ input.focus(); addMsg(`Thanks ${name}! How can I help you today?`); }
  });

  send.addEventListener("click",sendMsg);
  input.addEventListener("keydown",e=>{ if(e.key==="Enter"&&!e.shiftKey){ e.preventDefault(); sendMsg(); }});
  nameEl.addEventListener("keydown",e=>{ if(e.key==="Enter"){ e.preventDefault(); mailEl.focus(); }});
  mailEl.addEventListener("keydown",e=>{ if(e.key==="Enter"){ e.preventDefault(); saveBt.click(); }});

  if(leadCaptured){ addMsg(`Hi ${lead.name}! Welcome back to OneSource Cloud AI. How can I help with your infrastructure today?`); }
  else{ addMsg("Hi! I'm your OneSource Cloud AI assistant. Ask me about GPUs, data centers, or Private AI solutions!"); }
})();
